require(['jquery'], function($) {
  // Adds the fields of a new content fragment, numbered after the existing ones, so that the save action creates the
  // object holding it.
  $(document).on('click', '.docapp-fragment-add', function() {
    var container = $(this).closest('.docapp-fragments');
    var number = parseInt(container.attr('data-next-number'), 10);
    container.attr('data-next-number', number + 1);
    var fields = container.children('template.docapp-fragment-template').html().replace(/__number__/g, number);
    $(fields).insertBefore($(this).parent()).find('input[type="text"]').first().trigger('focus');
  });
  // Removes the fields of a content fragment that hasn't been saved yet.
  $(document).on('click', '.docapp-fragment-remove', function() {
    $(this).closest('.docapp-fragment').remove();
  });
});
